def fixture(tool, domain, level):
    """Input describes reproducible synthetic setup; no real infrastructure needed by default."""
    records = domain['records'][:1] if level == 0 else domain['records']
    result = {'records': records, 'business_contract': domain['contract'],
              'operation_fixtures': operation_fixtures(tool, level),
              'workspace': 'an isolated training directory; never a production target',
              'files': {'input.json': records, 'README.txt': domain['contract']},
              'environment': 'Use installed supported tool versions; record versions and commands. '
                             'For cloud operations use a permitted cost-bounded sandbox or provide a labelled local simulation; '
                             'a simulation does not establish cloud implementation acceptance.'}
    if level >= 1:
        result['lookup'] = [{'customer_id': records[0]['customer_id'], 'region': 'north'}]
    if level >= 4:
        result['manifest'] = ['source_a/input.json', 'source_b/input.json']
        result['source_b_records'] = [dict(records[0], source_system='source_b')]
    if level >= 6:
        result['failure_injection'] = 'Terminate after the bounded operation begins but before its success observation is recorded.'
    if tool in {'git', 'shell', 'docker', 'cicd'}:
        result['training_artifacts'] = {'transform.py': 'A tiny learner-owned transformation; retain original attempts.',
                                        'config.json': {'environment': 'scratch', 'input': 'input.json'},
                                        'unrelated.txt': 'This file belongs to another change and must remain intact.'}
    return result

def build(tool, seed):
    target = TARGETS[tool]
    original = [p for p in seed['problems'] if p['tool_id'] == tool]
    # Seed preservation is the loader's responsibility; external files contain additions.
    prefix = PREFIXES.get(tool) or original[0]['id'].rsplit('-', 1)[0][4:]
    next_number = max([int(p['id'].rsplit('-', 1)[1]) for p in original] or [0]) + 1
    remaining = target - len(original)
    base, extra = divmod(remaining, 11)
    result, previous, builds = [], original[-1]['id'] if original else None, {}
    for level in range(11):
        amount = base + (level < extra)
        assert amount <= len(FAMILIES[tool][level]) * len(MODES)
        for offset in range(amount):
            operation_index = offset % len(FAMILIES[tool][level])
            mode_index = offset // len(FAMILIES[tool][level])
            title, task, expected = FAMILIES[tool][level][operation_index]
            mode, action, proof, constraint = MODES[mode_index]
            missing_fixture = PENDING_FAMILIES.get(tool, {}).get(title)
            is_published = mode_index == 0 and not missing_fixture
            # A different contract changes the technical assumptions and the assessment,
            # not just a company name or a numeric literal.
            domain = DOMAINS[mode_index % len(DOMAINS)]
            pid = f'RLP-{prefix}-{next_number:03d}'
            next_number += 1
            built = builds.get((level, operation_index))
            inputs = fixture(tool, domain, level)
            if mode_index:
                inputs = {'draft_fixture_reference': built,
                          'records':domain['records'],
                          'changed_business_contract':domain['contract'],
                          'changed_boundary':domain['boundary'],
                          'status':'Draft: requires its own concrete technical fixture before publication.'}
            problem = {
                'id': pid, 'tool_id': tool,
                'title': f'{title} - {mode.replace("-", " ")}',
                'level': level, 'difficulty': f'level_{level}',
                'scenario': domain['business'] + f' Your bounded responsibility is: {title.lower()}.',
                'task': task + ' ' + action + ((' ' + domain['boundary']) if mode_index else ''),
                'inputs': inputs,
                'expected_output': {'operation_result': expected, 'required_evidence': proof,
                                    'business_contract': domain['contract']},
                'constraints': [constraint, 'Use only synthetic data and owned disposable training resources.',
                                'Preserve the original attempt and disclose documentation, AI and other assistance.',
                                domain['contract']],
                'acceptance_criteria': [expected, proof,
                                        'Provide actual commands or configuration, observed results, and the supplied input identity.',
                                        'Any simulated result is labelled simulation and cannot be reported as a real cloud deployment.'],
                'estimated_minutes': [10,15,20,25,35,45,50,60,70,90,120][level],
                'engineering_relevance': f'{title} is a bounded {tool} responsibility in {domain["name"]}. '
                                         'After verification, explain where the operation fits in the pipeline and one limitation exposed by this contract.',
                'official_docs': [DOCS[tool]],
                'learning_objective': title + ': ' + expected,
                'progressive_hints': [
                    'First write the promised observable result and identify which supplied input or artifact can establish it.',
                    f'Focus on this one responsibility: {task} Retain the smallest fixture that distinguishes correct behavior from a defect.',
                    f'Check the relevant official documentation for your recorded tool version, then compare the actual observation with: {expected}'
                ],
                'prerequisites': [previous] if previous else [],
                'skill_prerequisites': [] if level == 0 else [f'{tool}: level {level-1} bounded operations'],
                'independent_prerequisites': [],
                'challenge_kind': 'transfer' if mode_index else 'skill_build',
                'activity_mode': mode,
                'verification': {'kind': 'artifact_review',
                                 'evidence_required': ['implementation_or_configuration', 'observed_result', 'assistance_disclosure'],
                                 'note': 'Human review is required. No automatic correctness or cloud-execution claim is made.'},
                'published_version': VERSION,
                'publication_status': 'published' if is_published else 'draft',
                'draft_reason': missing_fixture or (None if mode_index == 0 else 'Needs a case-specific technical contract and supplied counterexample; generic assessment-mode expansion is not counted as a distinct published problem.'),
                'authoring': {'family': f'{tool}:{level}:{operation_index}', 'contract': domain['name'],
                              'batch': f'engineering:{tool}:L{level}', 'semantic_review': 'Explicit bounded operation family with synthetic fixture contract; learner correctness remains unassessed.'},
            }
            if tool == 'integrated-pipelines':
                gates = []
                if level >= 2: gates.extend(['RLP-PY-007','RLP-PG-002'])
                if level >= 4: gates.extend(['RLP-PY-011','RLP-SQL-008'])
                if level >= 7: gates.extend(['RLP-PYSPARK-001','RLP-DELTA-LAKE-001'])
                if level >= 9: gates.extend(['RLP-ADF-001','RLP-ADLS-001','RLP-DATABRICKS-001'])
                problem['prerequisites'].extend(gates)
            if built and mode_index:
                problem['transfer_of'] = built
            if not mode_index:
                builds[(level, operation_index)] = pid
            problem['followup'] = {'task': task + ' Reconstruct independently using the changed boundary.',
                                   'inputs': {'original_problem_id': pid, 'records':domain['records'],
                                              'changed_boundary': domain['boundary']},
                                   'expected_output': expected,
                                   'constraints': ['Disclose assistance and preserve the new attempt.', constraint],
                                   'verification': {'kind': 'artifact_review'}}
            result.append(problem)
            if is_published:
                previous = pid
    return result

def validate(problems):
    required = {'id','tool_id','title','scenario','task','inputs','expected_output','constraints',
                'acceptance_criteria','estimated_minutes','engineering_relevance','learning_objective',
                'progressive_hints','level','difficulty','prerequisites','skill_prerequisites','challenge_kind'}
    errors = []
    ids, signatures = set(), set()
    for p in problems:
        if required - p.keys(): errors.append(f'{p["id"]}: missing fields')
        if p['id'] in ids: errors.append(f'{p["id"]}: duplicate ID')
        ids.add(p['id'])
        signature = hashlib.sha256(json.dumps({k:p[k] for k in ['task','inputs','expected_output','constraints','acceptance_criteria']}, sort_keys=True).encode()).hexdigest()
        if signature in signatures: errors.append(f'{p["id"]}: duplicate contract')
        signatures.add(signature)
        if len(p['progressive_hints']) != 3: errors.append(f'{p["id"]}: expected three hints')
    for a,b in zip(problems, problems[1:]):
        if b['level'] < a['level'] or b['level'] > a['level']+1: errors.append(f'{b["id"]}: difficulty jump')
    return errors

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--tool', choices=sorted(TARGETS))
    parser.add_argument('--batch-limit', type=int, default=0,
                        help='Publish at most this many new technology files; rerun resumes by verified content digest.')
    args = parser.parse_args()
    seed = json.loads((ROOT/'tools/curriculum.json').read_text(encoding='utf-8'))
    checkpoint_path = OUT/'authors/engineering-checkpoint.json'
    checkpoint = json.loads(checkpoint_path.read_text()) if checkpoint_path.exists() else {'version':VERSION,'tracks':{}}
    published = 0
    for tool in ([args.tool] if args.tool else TARGETS):
        assert len(FAMILIES[tool]) == 11, tool
        problems = build(tool, seed)
        errors = validate(problems)
        if errors: raise ValueError(errors)
        published_count = sum(p['publication_status']=='published' for p in problems)
        draft_count = len(problems)-published_count
        original_count = sum(p['tool_id']==tool for p in seed['problems'])
        body = {'schema_version':1,'version':VERSION,'tool_id':tool,'target_total':TARGETS[tool],
                'actual_published_additions':published_count,'draft_candidates':draft_count,
                'seed_problem_ids':[p['id'] for p in seed['problems'] if p['tool_id']==tool],
                'problems':problems}
        content = json.dumps(body,indent=2,ensure_ascii=False)+'\n'
        digest = hashlib.sha256(content.encode()).hexdigest()
        path = OUT/f'{tool}.json'
        if path.exists():
            prior = json.loads(path.read_text(encoding='utf-8'))['problems']
            incoming = {p['id']:p for p in problems}
            for saved in prior:
                if saved['id'] not in incoming or incoming[saved['id']]['title'] != saved['title']:
                    raise ValueError('Refusing ID deletion/reassignment: '+saved['id']+'. Preserve existing IDs and author a separate appended batch.')
        if path.exists() and hashlib.sha256(path.read_bytes()).hexdigest() == digest:
            print(f'{tool}: resume verified {published_count} published additions; {draft_count} draft candidates')
        else:
            path.write_text(content,encoding='utf-8',newline='\n')
            published += 1
            print(f'{tool}: {published_count} published additions; {draft_count} drafts; target {TARGETS[tool]} remains unmet')
        checkpoint['tracks'][tool] = {'state':'partial_publication','candidate_additions':len(problems),
                                      'published_additions':published_count,'draft_candidates':draft_count,
                                      'actual_published_total_including_seed':published_count+original_count,
                                      'target_total':TARGETS[tool],
                                      'sha256':digest,'schema_errors':0,'duplicate_contracts':0,
                                      'semantic_limit':'Schema and contract distinction checked; meaningfulness requires pedagogical review.'}
        checkpoint_path.write_text(json.dumps(checkpoint,indent=2)+'\n',encoding='utf-8')
        if args.batch_limit and published >= args.batch_limit: break
    print('No learner completion, mastery, timer or revision evidence was created.')

if __name__ == '__main__':
    main()
